  var area=document.createElementNS(svgNS,'path');
  area.setAttribute('d',areaD);area.setAttribute('fill',color);area.setAttribute('fill-opacity','0.16');area.setAttribute('stroke','none');
  svg.appendChild(area);
  var line=document.createElementNS(svgNS,'path');
  line.setAttribute('d',lineD);line.setAttribute('fill','none');line.setAttribute('stroke',color);line.setAttribute('stroke-width','1.6');
