function hgStackedChart(root,seriesDefs,opts){
  opts=opts||{};
  if(!root)return;
  var rect=root.getBoundingClientRect();
  var W=Math.max(rect.width,80),H=Math.max(rect.height,60);
  var padL=opts.leftPad||34,padR=8,padT=8,padB=16;
  var plotW=Math.max(W-padL-padR,10),plotH=Math.max(H-padT-padB,10);
  var n=0;
  seriesDefs.forEach(function(s){if(s.v.length>n)n=s.v.length;});
  if(!n){root.innerHTML='<div class="hm-empty">sem dados</div>';return;}
  var tMin=seriesDefs[0].t[0],tMax=seriesDefs[0].t[seriesDefs[0].t.length-1];
  if(tMax===tMin)tMax=tMin+1;
  var maxTotal=0;
  for(var i=0;i<n;i++){var tot=0;seriesDefs.forEach(function(s){tot+=(s.v[i]||0);});if(tot>maxTotal)maxTotal=tot;}
  var yMax=opts.max||Math.max(maxTotal*1.15,10);
  function xOf(t){return padL+((t-tMin)/(tMax-tMin))*plotW;}
  function yOf(v){return padT+plotH-(v/yMax)*plotH;}
  var svgNS='http://www.w3.org/2000/svg';
  var svg=document.createElementNS(svgNS,'svg');
  svg.setAttribute('width','100%');svg.setAttribute('height','100%');svg.setAttribute('viewBox','0 0 '+W+' '+H);svg.style.display='block';svg.style.overflow='visible';
  function gline(y,txt){
    var l=document.createElementNS(svgNS,'line');l.setAttribute('x1',padL);l.setAttribute('x2',padL+plotW);l.setAttribute('y1',y);l.setAttribute('y2',y);l.setAttribute('stroke','rgba(255,255,255,.07)');svg.appendChild(l);
    var t=document.createElementNS(svgNS,'text');t.setAttribute('x',padL-6);t.setAttribute('y',y+3);t.setAttribute('fill','#7a8290');t.setAttribute('font-size','9');t.setAttribute('text-anchor','end');t.textContent=txt;svg.appendChild(t);
  }
  gline(padT,yMax.toFixed(0)+'%');gline(padT+plotH/2,(yMax/2).toFixed(0)+'%');gline(padT+plotH,'0%');
  if(opts.threshold!==undefined&&opts.threshold<=yMax){
    var ty=yOf(opts.threshold);
    var tl=document.createElementNS(svgNS,'line');tl.setAttribute('x1',padL);tl.setAttribute('x2',padL+plotW);tl.setAttribute('y1',ty);tl.setAttribute('y2',ty);
    tl.setAttribute('stroke','rgba(255,152,48,.55)');tl.setAttribute('stroke-width','1');tl.setAttribute('stroke-dasharray','4,3');svg.appendChild(tl);
    var lt=document.createElementNS(svgNS,'text');lt.setAttribute('x',padL+plotW-2);lt.setAttribute('y',ty-3);lt.setAttribute('fill','#ff9830');lt.setAttribute('font-size','9');lt.setAttribute('text-anchor','end');lt.textContent='ATENÇÃO '+opts.threshold+'%';svg.appendChild(lt);
  }
  var stackBase=new Array(n).fill(0);
  seriesDefs.forEach(function(s){
    var topPts=[],botPts=[];
    for(var i=0;i<n;i++){
      var v=s.v[i]||0;
      var base=stackBase[i];
      var top=base+v;
      topPts.push([xOf(s.t[i]),yOf(top)]);
      botPts.push([xOf(s.t[i]),yOf(base)]);
      stackBase[i]=top;
    }
    var d='M'+topPts.map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' L')+' L'+botPts.slice().reverse().map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' L')+' Z';
    var path=document.createElementNS(svgNS,'path');
    path.setAttribute('d',d);path.setAttribute('fill',s.color);path.setAttribute('fill-opacity','0.75');path.setAttribute('stroke',s.color);path.setAttribute('stroke-width','0.5');
    svg.appendChild(path);
  });
  var totalPts=[];
  for(var j=0;j<n;j++)totalPts.push([xOf(seriesDefs[0].t[j]),yOf(stackBase[j])]);
  var totalPath=document.createElementNS(svgNS,'path');
  totalPath.setAttribute('d','M'+totalPts.map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' L'));
  totalPath.setAttribute('fill','none');totalPath.setAttribute('stroke','rgba(255,255,255,.55)');totalPath.setAttribute('stroke-width','1.2');
  svg.appendChild(totalPath);
  var vline=document.createElementNS(svgNS,'line');vline.setAttribute('y1',padT);vline.setAttribute('y2',padT+plotH);vline.setAttribute('stroke','rgba(255,255,255,.3)');vline.style.display='none';svg.appendChild(vline);
  var tooltip=document.createElement('div');tooltip.className='hg-chart-tooltip';tooltip.style.display='none';tooltip.style.position='absolute';
  root.style.position='relative';
  svg.addEventListener('mousemove',function(ev){
    var r=svg.getBoundingClientRect();var mx=(ev.clientX-r.left)*(W/r.width);
    if(mx<padL||mx>padL+plotW){tooltip.style.display='none';vline.style.display='none';return;}
    var t=tMin+((mx-padL)/plotW)*(tMax-tMin);
    var bestI=0,bestD=Infinity;
    for(var k=0;k<seriesDefs[0].t.length;k++){var dd=Math.abs(seriesDefs[0].t[k]-t);if(dd<bestD){bestD=dd;bestI=k;}}
    vline.setAttribute('x1',mx);vline.setAttribute('x2',mx);vline.style.display='block';
    var rows=seriesDefs.map(function(s){return '<div class="hg-tt-row"><span class="hg-tt-dot" style="background:'+s.color+'"></span><span class="hg-tt-name">'+s.name+'</span><span class="hg-tt-val">'+(s.v[bestI]||0).toFixed(1)+'%</span></div>';}).join('');
    tooltip.innerHTML='<div class="hg-tt-time">'+new Date(seriesDefs[0].t[bestI]).toLocaleTimeString()+'</div>'+rows+'<div class="hg-tt-row"><b>total '+stackBase[bestI].toFixed(1)+'%</b></div>';
    tooltip.style.display='block';
    var left=ev.clientX-r.left+10;if(left+170>r.width)left=ev.clientX-r.left-180;
    tooltip.style.left=left+'px';tooltip.style.top=(ev.clientY-r.top-10)+'px';
  });
  svg.addEventListener('mouseleave',function(){tooltip.style.display='none';vline.style.display='none';});
  root.innerHTML='';root.appendChild(svg);root.appendChild(tooltip);
}

try{
  var root=hgEl('hg-root-10');
  var down=hgAllInstant('A'),up=hgAllInstant('B'),status=hgAllInstant('E');
  var downSeries=hgSeries('C'),upSeries=hgSeries('D');
  function peakOf(seriesArr,device){
    var f=seriesArr.find(function(s){return hgSeriesLabels(s).device===device;});
    if(!f)return null;
    var vals=hgFieldValues(hgNumField(f));
    var max=null;
    vals.forEach(function(v){if(v!==null&&v!==undefined&&!isNaN(v)){var mbps=v*8/1e6;if(max===null||mbps>max)max=mbps;}});
    return max;
  }
  var list=down.map(function(d){
    var device=d.labels.device;
    var dMbps=(d.v!==null&&d.v!==undefined)?d.v*8/1e6:null;
    var uEntry=up.find(function(x){return x.labels.device===device;});
    var uMbps=(uEntry&&uEntry.v!==null&&uEntry.v!==undefined)?uEntry.v*8/1e6:null;
    var st=status.find(function(x){return x.labels.device===device;});
    return {device:device,down:dMbps,up:uMbps,peakDown:peakOf(downSeries,device),peakUp:peakOf(upSeries,device),up_state:st?st.v:null};
  });
  list.sort(function(a,b){return ((b.down||0)+(b.up||0))-((a.down||0)+(a.up||0));});
  root.querySelector('[data-count]').textContent=list.length+' interfaces';
  root.querySelector('[data-rows]').innerHTML=list.map(function(x){
    var badge=x.up_state===1?'<span class="hm-badge ok">UP</span>':(x.up_state===0?'<span class="hm-badge crit">DOWN</span>':'<span class="hm-badge warn">?</span>');
