    '<div class="hm-iface-metric"><span>↑ <b>'+(x.up!==null?x.up.toFixed(1):'--')+' Mbps</b></span><span class="hm-iface-peak">pico '+(x.peakUp!==null?x.peakUp.toFixed(1):'--')+' Mbps</span></div>'+
    '</div>';
  }).join('')||'<div class="hm-empty">sem dados</div>';
}catch(e){}

options.css:
